#!/usr/bin/env bun
/** Regenerates schema/duckdb/envelope.v1.sql and src/ledger/schemas.ts from the schema files. */
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { duckdbDdl } from "../src/ledger/duckdb.js";
import envelope from "./envelope.v1.json";

const here = import.meta.dir;
writeFileSync(join(here, "duckdb/envelope.v1.sql"), duckdbDdl(envelope));

const files = readdirSync(join(here, "payload"))
	.filter((f) => f.endsWith(".v1.json"))
	.sort();
const lines = [
	"// Generated by `bun schema/build.ts`: the schema files, imported so the built library carries them.",
	'import envelope from "../../schema/envelope.v1.json";',
	...files.map((f, i) => `import p${i} from "../../schema/payload/${f}";`),
	"",
	"export const envelopeSchema: Record<string, unknown> = envelope;",
	"export const payloadSchemas: Record<string, Record<string, unknown>> = {",
	...files.map((f, i) => `\t"${f.replace(".v1.json", "")}": p${i},`),
	"};",
	"",
];
writeFileSync(join(here, "../src/ledger/schemas.ts"), lines.join("\n"));
console.log("wrote duckdb/envelope.v1.sql and src/ledger/schemas.ts");
